import boto3

def dead_letter(payload, config=None):
    config = config or {}
    aws_region = config.get('aws_region') or os.environ.get('AWS_REGION')
    queue_url = config.get('queue_url') or os.environ.get('AWS_SQS_DEAD_LETTER_QUEUE_URL')

    if not queue_url:
        raise ValueError("SQS dead-letter queue URL must be set in config or AWS_SQS_DEAD_LETTER_QUEUE_URL env var.")

    sqs_client = boto3.client("sqs", region_name=aws_region)
    result = sqs_client.send_message(
        QueueUrl=queue_url,
        MessageBody=str(payload)
    )
    return result
